pub(super) fn csign(
    room_id: u32,
    device_id: &str,
    timestamp: u64,
    params: &BTreeMap<String, String>,
) -> String {
    let mut values = params.clone();
    for key in ["csign", "amd", "host", "name_time"] {
        values.remove(key);
    }
    values.insert("cptl".into(), "0103".into());
    values.insert("client_sys".into(), "android".into());
    let canonical = values
        .iter()
        .map(|(k, v)| format!("{k}={v}"))
        .collect::<Vec<_>>()
        .join("&");
    let prefix = format!(
        "{room_id}{device_id}{timestamp}0103{}",
        SALTS[room_id as usize % 200]
    );
    let mut hasher = Md5::new();
    hasher.update(prefix.as_bytes());
    hasher.update(canonical.as_bytes());
    let digest = hasher.finalize();
    let mut key = [0u8; 10];
    let len = prefix.len().min(10);
    key[..len].copy_from_slice(&prefix.as_bytes()[..len]);
    let sbox = hex_bytes(SBOX);
    let mut table = [0u8; 2560];
    for (block, byte) in key.iter().enumerate() {
        for j in 0..256 {
            table[block * 256 + j] = sbox[j ^ *byte as usize] ^ 0xc3;
        }
    }
    let mut transformed = [0u8; 16];
    transformed[..8].copy_from_slice(&transform(&digest[..8], &table));
    transformed[8..].copy_from_slice(&transform(&digest[8..], &table));
    let map = hex_bytes(MAPS[room_id as usize % 200]);
    transformed
        .iter()
        .map(|b| format!("{:02x}", map[*b as usize]))
        .collect()
}

pub(super) fn amd(signature: &str, device_id: &str) -> String {
    let key = hex_bytes(signature);
    let words: Vec<u32> = key
        .chunks_exact(4)
        .map(|b| u32::from_le_bytes(b.try_into().unwrap()))
        .collect();
    let mut state = [0u8; 88];
    state[0..8].copy_from_slice(&0u64.to_le_bytes());
    state[8..12].copy_from_slice(&1u32.to_le_bytes());
    state[12..16].copy_from_slice(&1u32.to_le_bytes());
    state[36..52].copy_from_slice(&hex_bytes(SAMPLE_STATE));
    let did = device_id.as_bytes();
    state[52..52 + did.len().min(36)].copy_from_slice(&did[..did.len().min(36)]);
    let mut result = Vec::with_capacity(88);
    for pair in state.chunks_exact(8) {
        let mut a = u32::from_le_bytes(pair[..4].try_into().unwrap());
        let mut b = u32::from_le_bytes(pair[4..].try_into().unwrap());
        let mut sum = 0u32;
        for _ in 0..32 {
            sum = sum.wrapping_add(0x9e3779b9);
            a = a.wrapping_add(
                ((b << 4).wrapping_add(words[0]))
                    ^ b.wrapping_add(sum)
                    ^ ((b >> 5).wrapping_add(words[1])),
            );
            b = b.wrapping_add(
                ((a << 4).wrapping_add(words[2]))
                    ^ a.wrapping_add(sum)
                    ^ ((a >> 5).wrapping_add(words[3])),
            );
        }
        result.extend_from_slice(&a.to_le_bytes());
        result.extend_from_slice(&b.to_le_bytes());
    }
    result.iter().map(|b| format!("{b:02x}")).collect()
}

pub(super) fn header_auth(
    path: &str,
    timestamp: u64,
    aid: &str,
    params: &BTreeMap<String, String>,
) -> String {
    let mut values = params.clone();
    for key in [
        "client_sys",
        "host",
        "name_time",
        "retryTimes",
        "auth_position",
        "replaceParameter",
        "get_params_order",
    ] {
        values.remove(key);
    }
    values.insert("aid".into(), aid.into());
    values.insert("client_sys".into(), "android".into());
    values.insert("time".into(), timestamp.to_string());
    let canonical = values
        .iter()
        .map(|(k, v)| format!("{k}={v}"))
        .collect::<Vec<_>>()
        .join("&");
    let source = format!(
        "{}?{canonical}vq47Hd9JUgfDCytC",
        path.trim_start_matches('/')
    );
    let mut hasher = Md5::new();
    hasher.update(source.as_bytes());
    format!("{:x}", hasher.finalize())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn android_signature_matches_reference() {
        let mut params = BTreeMap::new();
        for (key, value) in [
            ("txdw", "0"),
            ("cdn", "hw"),
            ("dscnt", "0"),
            ("token", ""),
            ("rate", "0"),
            ("hevc", "0"),
            ("ilow", "0"),
            ("iar", "0"),
            ("net", "WIFI"),
            ("device", "PHK110"),
        ] {
            params.insert(key.to_string(), value.to_string());
        }
        let timestamp = 1790312470;
        let signature = csign(1126960, DEFAULT_DEVICE_ID, timestamp, &params);
        assert_eq!(signature, "26660e9d8e79f3476e02b14d4c481353");
        let encrypted = amd(&signature, DEFAULT_DEVICE_ID);
        assert_eq!(
            encrypted,
            "a76343b9f45e3a695db3c213b25dfbb9a76343b9f45e3a69a76343b9f45e3a69a76343b9f45e3a69a76343b9f45e3a690a1f3a34734a7149f5bada1c778c0633f5bada1c778c0633f5bada1c778c06335420cc761ed6e0cf"
        );
        params.insert("csign".into(), signature);
        params.insert("cptl".into(), "0103".into());
        params.insert("amd".into(), encrypted);
        params.insert("client_sys".into(), "android".into());
        assert_eq!(
            header_auth(
                "/lapi/live/appGetPlayer/stream/1126960",
                timestamp,
                "android1",
                &params
            ),
            "f38e7b58edb31472f7c79e43ee1a6969"
        );
    }
}
